CREATE PROCEDURE [EcsMacchine_bulkupdate]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
	@changeTable [EcsMacchine_BulkType] READONLY
AS
BEGIN
-- use a temp table to store the list of PKs that successfully got updated
declare @changed TABLE ([CodMac] varchar(15), PRIMARY KEY ([CodMac]));

-- update the base table
MERGE [EcsMacchine] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [EcsMacchine_tracking] t ON p.[CodMac] = t.[CodMac]) as changes ON changes.[CodMac] = base.[CodMac]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp THEN
UPDATE SET [Keys] = changes.[Keys], [Modu] = changes.[Modu], [NomMac] = changes.[NomMac], [Tipo] = changes.[Tipo], [ValIn1] = changes.[ValIn1], [ValIn2] = changes.[ValIn2], [ValIn3] = changes.[ValIn3], [ValIn4] = changes.[ValIn4], [ValIn5] = changes.[ValIn5], [ValIn6] = changes.[ValIn6], [ValIn7] = changes.[ValIn7], [ValIn8] = changes.[ValIn8], [ValIn9] = changes.[ValIn9], [ValIn10] = changes.[ValIn10], [ValIn11] = changes.[ValIn11], [ValIn12] = changes.[ValIn12], [ValIn13] = changes.[ValIn13], [ValIn14] = changes.[ValIn14], [ValIn15] = changes.[ValIn15], [ValIn16] = changes.[ValIn16], [TipoIn1] = changes.[TipoIn1], [TipoIn2] = changes.[TipoIn2], [TipoIn3] = changes.[TipoIn3], [TipoIn4] = changes.[TipoIn4], [TipoIn5] = changes.[TipoIn5], [TipoIn6] = changes.[TipoIn6], [TipoIn7] = changes.[TipoIn7], [TipoIn8] = changes.[TipoIn8], [TipoIn9] = changes.[TipoIn9], [TipoIn10] = changes.[TipoIn10], [TipoIn11] = changes.[TipoIn11], [TipoIn12] = changes.[TipoIn12], [TipoIn13] = changes.[TipoIn13], [TipoIn14] = changes.[TipoIn14], [TipoIn15] = changes.[TipoIn15], [TipoIn16] = changes.[TipoIn16], [CntrLet1] = changes.[CntrLet1], [CntrLet2] = changes.[CntrLet2], [CntrLet3] = changes.[CntrLet3], [CntrLet4] = changes.[CntrLet4], [CntrLet5] = changes.[CntrLet5], [CntrLet6] = changes.[CntrLet6], [CntrLet7] = changes.[CntrLet7], [CntrLet8] = changes.[CntrLet8], [CntrLet9] = changes.[CntrLet9], [CntrLet10] = changes.[CntrLet10], [CntrLet11] = changes.[CntrLet11], [CntrLet12] = changes.[CntrLet12], [CntrLet13] = changes.[CntrLet13], [CntrLet14] = changes.[CntrLet14], [CntrLet15] = changes.[CntrLet15], [CntrLet16] = changes.[CntrLet16], [CntrVal1] = changes.[CntrVal1], [CntrVal2] = changes.[CntrVal2], [CntrVal3] = changes.[CntrVal3], [CntrVal4] = changes.[CntrVal4], [CntrVal5] = changes.[CntrVal5], [CntrVal6] = changes.[CntrVal6], [CntrVal7] = changes.[CntrVal7], [CntrVal8] = changes.[CntrVal8], [CntrVal9] = changes.[CntrVal9], [CntrVal10] = changes.[CntrVal10], [CntrVal11] = changes.[CntrVal11], [CntrVal12] = changes.[CntrVal12], [CntrVal13] = changes.[CntrVal13], [CntrVal14] = changes.[CntrVal14], [CntrVal15] = changes.[CntrVal15], [CntrVal16] = changes.[CntrVal16], [InCnt1] = changes.[InCnt1], [InCnt2] = changes.[InCnt2], [InCnt3] = changes.[InCnt3], [InCnt4] = changes.[InCnt4], [InCnt5] = changes.[InCnt5], [InCnt6] = changes.[InCnt6], [InCnt7] = changes.[InCnt7], [InCnt8] = changes.[InCnt8], [InCnt9] = changes.[InCnt9], [InCnt10] = changes.[InCnt10], [InCnt11] = changes.[InCnt11], [InCnt12] = changes.[InCnt12], [InCnt13] = changes.[InCnt13], [InCnt14] = changes.[InCnt14], [InCnt15] = changes.[InCnt15], [InCnt16] = changes.[InCnt16], [RapCnt1] = changes.[RapCnt1], [RapCnt2] = changes.[RapCnt2], [RapCnt3] = changes.[RapCnt3], [RapCnt4] = changes.[RapCnt4], [RapCnt5] = changes.[RapCnt5], [RapCnt6] = changes.[RapCnt6], [RapCnt7] = changes.[RapCnt7], [RapCnt8] = changes.[RapCnt8], [RapCnt9] = changes.[RapCnt9], [RapCnt10] = changes.[RapCnt10], [RapCnt11] = changes.[RapCnt11], [RapCnt12] = changes.[RapCnt12], [RapCnt13] = changes.[RapCnt13], [RapCnt14] = changes.[RapCnt14], [RapCnt15] = changes.[RapCnt15], [RapCnt16] = changes.[RapCnt16], [Propr] = changes.[Propr], [PerDiv] = changes.[PerDiv], [DataInst] = changes.[DataInst], [DataDis] = changes.[DataDis], [ValPar] = changes.[ValPar], [NImp] = changes.[NImp], [F0] = changes.[F0], [T0] = changes.[T0], [N0] = changes.[N0], [D0] = changes.[D0], [ValPiatto] = changes.[ValPiatto], [PzPiatto] = changes.[PzPiatto], [device] = changes.[device], [IngressoCrediti] = changes.[IngressoCrediti], [IngressoGettoni] = changes.[IngressoGettoni], [IngressoTickets] = changes.[IngressoTickets], [device_status] = changes.[device_status], [lastseen] = changes.[lastseen], [offlinecount] = changes.[offlinecount], [onlinecount] = changes.[onlinecount], [cards_presentate] = changes.[cards_presentate], [val_platinum] = changes.[val_platinum], [val_gold] = changes.[val_gold], [val_silver] = changes.[val_silver], [val_normal] = changes.[val_normal], [is_happyhour] = changes.[is_happyhour], [is_timeplay] = changes.[is_timeplay], [is_online] = changes.[is_online]
OUTPUT INSERTED.[CodMac] into @changed; -- populates the temp table with successful PKs

UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[EcsMacchine_tracking] side JOIN 
(SELECT p.[CodMac], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[CodMac] = t.[CodMac]) as changes ON changes.[CodMac] = side.[CodMac]
SELECT [CodMac] FROM @changeTable t WHERE NOT EXISTS (SELECT [CodMac] from @changed i WHERE t.[CodMac] = i.[CodMac])
END
